const enc=new TextEncoder();
async function sha(s){return new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(s)))}
function hex(bytes){return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('')}
async function mac(key,text){const k=await crypto.subtle.importKey('raw',enc.encode(key),{name:'HMAC',hash:'SHA-256'},false,['sign']);return hex(new Uint8Array(await crypto.subtle.sign('HMAC',k,enc.encode(text))))}
function equal(a,b){if(a.length!==b.length)return false;let x=0;for(let i=0;i<a.length;i++)x|=a.charCodeAt(i)^b.charCodeAt(i);return x===0}
async function adminAuth(req,env){if(!env.ADMIN_SESSION_SECRET||env.ADMIN_SESSION_SECRET.length<32)return false;const v=(req.headers.get('cookie')||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('bioryx_admin='))?.slice(13)||'';const parts=v.split('.');if(parts.length!==2||!/^\d{10,13}$/.test(parts[0])||Number(parts[0])<Date.now()||Number(parts[0])>Date.now()+14400000)return false;return equal(await mac(env.ADMIN_SESSION_SECRET,parts[0]),parts[1])}
