 retention:{columns:['customer_type','customers','orders','net_paid_goods_rub'],sql:"WITH bounds AS (SELECT ? start,datetime(?,'+1 day') finish),first_orders AS (SELECT f.customer_id,MIN(o.created_at) first_date FROM orders o JOIN bx_order_finance f ON f.order_id=o.id WHERE f.customer_id IS NOT NULL AND o.status='delivered' AND o.payment_status='paid' GROUP BY f.customer_id),period_orders AS (SELECT f.customer_id,COUNT(*) orders,SUM(o.total) net_paid_goods_rub FROM orders o JOIN bx_order_finance f ON f.order_id=o.id CROSS JOIN bounds b WHERE f.customer_id IS NOT NULL AND o.created_at>=b.start AND o.created_at<b.finish AND o.status='delivered' AND o.payment_status='paid' GROUP BY f.customer_id) SELECT CASE WHEN fo.first_date<(SELECT start FROM bounds) THEN 'repeat' ELSE 'first' END customer_type,COUNT(*) customers,SUM(po.orders) orders,SUM(po.net_paid_goods_rub) net_paid_goods_rub FROM period_orders po JOIN first_orders fo ON fo.customer_id=po.customer_id GROUP BY CASE WHEN fo.first_date<(SELECT start FROM bounds) THEN 'repeat' ELSE 'first' END UNION ALL SELECT 'unlinked',NULL,COUNT(*),COALESCE(SUM(o.total),0) FROM orders o LEFT JOIN bx_order_finance f ON f.order_id=o.id CROSS JOIN bounds b WHERE f.customer_id IS NULL AND o.created_at>=b.start AND o.created_at<b.finish AND o.status='delivered' AND o.payment_status='paid' LIMIT 5001"},
 balances:{columns:['level_id','level_name','customers','positive_points','negative_points','net_points'],sql:"WITH balances AS (SELECT c.id,COALESCE((SELECT SUM(l.points) FROM bx_loyalty_ledger l WHERE l.customer_id=c.id),0) balance,COALESCE((SELECT level FROM bx_customer_levels WHERE customer_id=c.id),(SELECT l.id FROM bx_club_levels l WHERE l.threshold<=COALESCE((SELECT SUM(o.total) FROM orders o JOIN bx_order_finance f ON f.order_id=o.id WHERE f.customer_id=c.id AND o.status='delivered' AND o.payment_status='paid'),0) ORDER BY l.threshold DESC LIMIT 1)) level FROM bx_customers c) SELECT l.id level_id,l.title level_name,COUNT(b.id) customers,COALESCE(SUM(CASE WHEN b.balance>0 THEN b.balance ELSE 0 END),0) positive_points,COALESCE(SUM(CASE WHEN b.balance<0 THEN b.balance ELSE 0 END),0) negative_points,COALESCE(SUM(b.balance),0) net_points FROM bx_club_levels l LEFT JOIN balances b ON b.level=l.id GROUP BY l.id,l.title ORDER BY l.threshold LIMIT 5001",noPeriod:true},
